            for (Object value : this.data.get(i).getValue()) {
                System.out.print(value + ", ");
            }
            System.out.println();
        }
    }

    private void checkIndex(int index) {
        if (!this.data.containsKey(index)) {
            throw new RuntimeException("Index out of bounds: " + index);
        }
    }

    // Other methods
    public DfCell get(int row, int column) {
        return this.data.get(row).getValue(column);
    }

    public void set(int row, int column, Object value) {
        ((DfCell) this.data.get(row)).setValue(value);
    }

